def refs(fs):
 arr=[]
 for f in fs:
  path=(probe/f) if (probe/f).is_file() else (e/f)
  assert path.is_file(),f
  arr.append({'file':str(path.relative_to(e)).replace('\\','/'),'sha256':h(path)})
 return arr
